        double identityError=0;hair::CsRandom random{912773};for(unsigned i=0;i<128;i++){windowmath::PositionProblem p;auto vec=[&](){return D{random.sample()-.5,random.sample()-.5,random.sample()-.5};};p.x=vec();p.y=vec();p.left=vec();p.right=vec();p.tl=vec();p.tr=vec();p.a=.1+5*random.sample();p.cl=i%3?20*random.sample():0;p.cr=i%4?30*random.sample():0;auto minimum=windowmath::positionMinimum(p),delta=minimum-p.x;double diagonal=p.a+p.cl+p.cr;for(double omega:{1.,1.8,1.95}){double actual=windowmath::localEnergy(p,p.x+omega*delta)-windowmath::localEnergy(p,p.x);double expected=-.5*omega*(2-omega)*diagonal*delta.dot(delta);identityError=std::max(identityError,std::abs(actual-expected)/std::max(1.,std::abs(expected)));}}require(identityError<1e-12,"SOR local energy identity failed");
