        std::ostringstream out;out.precision(17);out<<"{\"initializer\":"<<o.initializer<<",\"positionError\":"<<px<<",\"velocityError\":"<<pv<<",\"passed\":"<<(px<5e-6&&pv<2e-4?"true":"false")<<",\"historyResetZero\":true,\"sorEnergyIdentityError\":"<<identityError<<"}";write(o.output,out.str());require(px<5e-6&&pv<2e-4,"Analytic uniform free-fall response failed");
